            column = [board[row][col] for row in range(9)]
            if len(set(column)) != 9:
                return False

        # Check 3x3 subgrids
        for row_start in range(0, 9, 3):
            for col_start in range(0, 9, 3):
                subgrid = []
                for row in range(row_start, row_start + 3):
